import '../css/Login.css';
import { useNavigate } from 'react-router-dom';

export default function Login(props) {
  const navigate = useNavigate();
  async function userLogin(event){
      // Prevent the default form submission behavior
      event.preventDefault();
      event.stopPropagation();
      var username = document.querySelector('.username').value;
      var password = document.querySelector('.password').value;
      const params = new URLSearchParams({
        username: username,
        password: password
      });
      try {
        const response = fetch(
          `http://localhost:8080/userLogin?${params}`
        );

        response.then(async (res) => {
          if (!res.ok) {
            const msg = await res.text();
            throw new Error(msg);
          }

          return res.text();
        })
        .then((data) => {
          navigate('/');
        })
        .catch((error) => {
          alert("Credentials are invalid. Please try again.");
        });
      } catch (error) {
        console.error("Error:", error);
      }
    }
  return (
    <div className="loginContainer">
        <span className="loginHeader">
            <h2>Welcome</h2>
            <p>Sign in to your account</p>
        </span>
        <form className="loginForm">
            <label className="loginLabel">
            Username
            <input type="text" className="username" name="username" placeholder="Enter your username" />
            </label>
            <br />
            <label className="loginLabel">
            Password
            <input type="password" className="password" name="password" placeholder="Enter your password" />
            </label>
            <br />
            <button className="loginButton" type="submit" onClick={userLogin}>Login</button>
            <p>Don't have an account? <a href="/signup" className='signupLink'>Sign up</a></p>
        </form>
    </div>
  );
}
